// Synthetic three-level union repeaters generated by typegen's required-combinations.mjs.
// These requests are compiled only and never executed.
import { createClient, type InferMicroCMSContent } from '../../../..';
import type { MainServiceSchema as Schema } from './required-combinations';
type Assert<T extends true> = T;
type SameShape<A, B> = [A] extends [B] ? [B] extends [A] ? true : false : false;
const client = createClient<Schema>({ serviceDomain: 'fixture', apiKey: 'TYPE_ONLY' });
type Create = Schema['pages']['create'];
type Section = Extract<Create['blocks'][number], { fieldId: 'section' }>;
type Group = Extract<Section['groups'][number], { fieldId: 'group' }>;
const group: Group = { fieldId: 'group', enabled: false, items: [
  { fieldId: 'text', body: 'text' },
  { fieldId: 'link', label: 'link', target: 'id', targets: ['id'], tags: ['one'] },
] };
const section: Section = { fieldId: 'section', heading: 'heading', groups: [group, { fieldId: 'text', body: 'sibling' }] };
const content: Create = { title: 'title', blocks: [section, { fieldId: 'text', body: 'top sibling' }] };
client.create({ endpoint: 'pages', content });
client.update({ endpoint: 'settings', content: { blocks: [section] } });
client.update({ endpoint: 'settings', content: { title: 'updated' } });
client.update({ endpoint: 'settings', content: { details: {} } });
// @ts-expect-error object updates retain the nonempty tuple constraint
client.update({ endpoint: 'settings', content: { blocks: [] } });
// @ts-expect-error required children apply when an optional custom parent is supplied
client.update({ endpoint: 'settings', content: { details: { fieldId: 'section', heading: 'heading' } } });
// @ts-expect-error nested replacement elements require a boolean even when false is valid
client.update({ endpoint: 'settings', content: { blocks: [{ fieldId: 'section', heading: 'heading', groups: [{ fieldId: 'group', items: [{ fieldId: 'text', body: 'text' }] }] }] } });
// @ts-expect-error the third repeater level preserves its nonempty constraint
client.update({ endpoint: 'settings', content: { blocks: [{ fieldId: 'section', heading: 'heading', groups: [{ fieldId: 'group', enabled: false, items: [] }] }] } });
const mixed = { fieldId: 'text' as const, body: 'text', label: 'another variant' };
// @ts-expect-error a variable cannot borrow another variant's keys at the third level
client.update({ endpoint: 'settings', content: { blocks: [{ fieldId: 'section', heading: 'heading', groups: [{ fieldId: 'group', enabled: false, items: [mixed] }] }] } });

const queries = { depth: 2, fields: ['id', 'title', 'blocks'] } as const;
const list = client.getList({ endpoint: 'pages', queries });
type Selected = Awaited<typeof list>['contents'][number];
type Title = Assert<SameShape<Selected['title'], string>>;
type Extracted = Assert<SameShape<Selected, InferMicroCMSContent<Schema, 'pages', typeof queries>>>;
type ReadBlocks = Selected['blocks'];
type NonemptyBlocks = Assert<SameShape<ReadBlocks, [ReadBlocks[number], ...ReadBlocks[number][]]>>;
type ReadSection = Extract<ReadBlocks[number], { fieldId: 'section' }>;
type ReadGroup = Extract<ReadSection['groups'][number], { fieldId: 'group' }>;
type NonemptyGroups = Assert<SameShape<ReadSection['groups'], [ReadSection['groups'][number], ...ReadSection['groups'][number][]]>>;
type NonemptyItems = Assert<SameShape<ReadGroup['items'], [ReadGroup['items'][number], ...ReadGroup['items'][number][]]>>;
// @ts-expect-error selected SDK reads retain the generated nonempty constraint
const emptySelectedBlocks: ReadBlocks = [];
// @ts-expect-error type extraction retains the generated nonempty constraint
const emptyExtractedBlocks: InferMicroCMSContent<Schema, 'pages', typeof queries>['blocks'] = [];
// @ts-expect-error third-level SDK reads retain the generated nonempty constraint
const emptyReadItems: ReadGroup['items'] = [];

const object = client.getObject({ endpoint: 'settings', queries: { fields: ['title', 'blocks'], depth: 2 } });
type Object = Awaited<typeof object>;
type ObjectId = Assert<SameShape<'id' extends keyof Object ? true : false, false>>;
type ObjectTitle = Assert<SameShape<Object['title'], string>>;
// @ts-expect-error selected object reads retain the generated nonempty constraint
const emptyObjectReadBlocks: Object['blocks'] = [];

const full = client.getObject({ endpoint: 'settings' });
type FullObject = Assert<SameShape<Awaited<typeof full>, Schema['settings']['depths'][1]>>;
// @ts-expect-error object reads cannot select id
client.getObject({ endpoint: 'settings', queries: { fields: ['id'] } });
// @ts-expect-error object updates cannot specify contentId
client.update({ endpoint: 'settings', contentId: 'id', content: { title: 'updated' } });
// @ts-expect-error object APIs cannot create new list contents
client.create({ endpoint: 'settings', content });
